def split_csv(line):
    n = len(line)
    if n == 0:
        return [""]

    fields = []
    i = 0

    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            field_chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    field_chars.append(c)
                    i += 1
            if not closed:
                return None  # unterminated quoted field

            fields.append(''.join(field_chars))

            if i == n:
                break
            elif line[i] == ',':
                i += 1
                if i == n:
                    fields.append('')
                    break
                # else continue loop to parse next field
            else:
                return None  # closing quote not followed by comma or end
        else:
            start = i
            while i < n and line[i] != ',' and line[i] != '"':
                i += 1
            if i < n and line[i] == '"':
                return None  # quote inside unquoted field
            fields.append(line[start:i])

            if i == n:
                break
            elif line[i] == ',':
                i += 1
                if i == n:
                    fields.append('')
                    break
            else:
                return None

    return fields

